import{_ as t}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as a,c as o,a as s}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const f=JSON.parse(`{"title":"What's new in v1.8.0","description":"Purple TUI theme, fetch progress bar, position indicator, line-anchored file links, and Esc to close help.","frontmatter":{"title":"What's new in v1.8.0","description":"Purple TUI theme, fetch progress bar, position indicator, line-anchored file links, and Esc to close help.","date":"2026-03-04T00:00:00.000Z"},"headers":[],"relativePath":"blog/release-v1-8-0.md","filePath":"blog/release-v1-8-0.md"}`),r={name:"blog/release-v1-8-0.md"};function i(l,e,h,n,d,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="what-s-new-in-github-code-search-v1-8-0" tabindex="-1">What&#39;s new in github-code-search v1.8.0 <a class="header-anchor" href="#what-s-new-in-github-code-search-v1-8-0" aria-label="Permalink to &quot;What&#39;s new in github-code-search v1.8.0&quot;">​</a></h1><blockquote><p>Full release notes: <a href="https://github.com/fulll/github-code-search/releases/tag/v1.8.0" target="_blank" rel="noreferrer">https://github.com/fulll/github-code-search/releases/tag/v1.8.0</a></p></blockquote><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="cohesive-purple-tui-theme" tabindex="-1">Cohesive purple TUI theme <a class="header-anchor" href="#cohesive-purple-tui-theme" aria-label="Permalink to &quot;Cohesive purple TUI theme&quot;">​</a></h3><p>The interactive view has been completely re-skinned around a purple colour palette.</p><table tabindex="0"><thead><tr><th>Element</th><th>Before</th><th>After</th></tr></thead><tbody><tr><td>Active row background</td><td>Grey (<code>48;5;236</code>)</td><td>Dark purple (<code>48;5;53</code>)</td></tr><tr><td>Active row left bar <code>▌</code></td><td>None</td><td>Saturated purple (<code>38;5;129</code>)</td></tr><tr><td>Repo names</td><td>Bold cyan</td><td>Bright purple bold (<code>38;5;129</code>)</td></tr><tr><td>Match count badge</td><td>Dim white</td><td>Muted purple (<code>38;5;99</code>)</td></tr></tbody></table><p>The left bar spans the full terminal width so the selected row is unmistakable even in long result lists. Path and loc-suffix (<code>:line:col</code>) on the active extract row use <strong>bold white</strong> for visual consistency.</p><h3 id="fetch-progress-bar" tabindex="-1">Fetch progress bar <a class="header-anchor" href="#fetch-progress-bar" aria-label="Permalink to &quot;Fetch progress bar&quot;">​</a></h3><p>A progress bar is now displayed during the GitHub API search so you can track paged requests in real time:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>Fetching results ████████████████░░░░░░░░  8/13 pages</span></span></code></pre></div><p>The bar fills in saturated purple and shows the current page / estimated total pages. It disappears automatically when all results are loaded.</p><h3 id="position-indicator" tabindex="-1">Position indicator <a class="header-anchor" href="#position-indicator" aria-label="Permalink to &quot;Position indicator&quot;">​</a></h3><p>A persistent indicator at the bottom of the TUI shows your exact position within the result list:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>  ↕ row 14 of 49</span></span></code></pre></div><p>The number always reflects the <strong>cursor position</strong>, not the scroll offset, so it updates on every keypress — including when you navigate upward inside an already-scrolled viewport.</p><h3 id="line-anchored-file-links-o" tabindex="-1">Line-anchored file links (<code>o</code>) <a class="header-anchor" href="#line-anchored-file-links-o" aria-label="Permalink to &quot;Line-anchored file links (`o`)&quot;">​</a></h3><p>When you press <code>o</code> on an <strong>extract row</strong>, the browser now opens the file at the <strong>exact matched line</strong> by appending a <code>#L{line}</code> anchor to the GitHub URL.</p><p>Before: <code>https://github.com/org/repo/blob/main/src/foo.ts</code><br> After: <code>https://github.com/org/repo/blob/main/src/foo.ts#L42</code></p><p>On a <strong>repo row</strong>, <code>o</code> still opens the repository home page unchanged.</p><h3 id="esc-to-close-the-help-overlay" tabindex="-1">Esc to close the help overlay <a class="header-anchor" href="#esc-to-close-the-help-overlay" aria-label="Permalink to &quot;Esc to close the help overlay&quot;">​</a></h3><p>The help overlay (toggled with <code>h</code> or <code>?</code>) can now also be dismissed with <code>Esc</code>, matching the expected behaviour of most terminal UIs.</p><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>Or grab the latest binary directly from the <a href="https://github.com/fulll/github-code-search/releases/tag/v1.8.0" target="_blank" rel="noreferrer">GitHub Releases page</a>.</p>',25)])])}const v=t(r,[["render",i]]);export{f as __pageData,v as default};
